use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, RwLock};
use std::thread;

fn main() {
    let hits = Arc::new(AtomicUsize::new(0));
    let config = Arc::new(RwLock::new(String::from("v1")));

    thread::scope(|s| {
        for _ in 0..4 {
            s.spawn(|| {
                for _ in 0..1000 {
                    hits.fetch_add(1, Ordering::Relaxed);
                }
                let _version = config.read().unwrap(); // many readers at once
            });
        }
    });

    *config.write().unwrap() = String::from("v2"); // one writer
    println!("hits = {}", hits.load(Ordering::Relaxed));
    println!("config = {}", config.read().unwrap());
}

