use std::cell::RefCell;
use std::rc::Rc;
use std::thread;

fn main() {
    let balance = Rc::new(RefCell::new(0i64));
    let mut handles = Vec::new();
    for _ in 0..4 {
        let balance = Rc::clone(&balance);
        handles.push(thread::spawn(move || {
            for _ in 0..250 {
                *balance.borrow_mut() += 1;
            }
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    println!("balance = {}", balance.borrow());
}
